import{_ as s,o as e,c as t,a2 as p}from"./chunks/framework.EUByU7Iq.js";const d=JSON.parse('{"title":"公刘","description":"","frontmatter":{"title":"公刘","date":"2026-11-09T00:00:00.000Z","seq":16,"categories":["美文","诗经"],"collection":"《诗经 · 大雅》","tags":["诗经","先秦"],"poem":true,"author":"佚名","source_book":"诗经"},"headers":[],"relativePath":"blogs/诗经·大雅/公刘.md","filePath":"blogs/诗经·大雅/公刘.md"}'),o={name:"blogs/诗经·大雅/公刘.md"};function c(l,a,n,r,m,_){return e(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="公刘" tabindex="-1">公刘 <a class="header-anchor" href="#公刘" aria-label="Permalink to &quot;公刘&quot;">​</a></h1><p class="poem-meta">先秦 · 佚名　·　生民之什</p><div class="poem"><p class="poem-stanza">笃公刘，匪居匪康。乃埸乃疆，乃积乃仓；乃裹餱粮，于橐于囊。</p><p class="poem-stanza">思辑用光，弓矢斯张；干戈戚扬，爰方启行。</p><p class="poem-stanza">笃公刘，于胥斯原。既庶既繁，既顺乃宣，而无永叹。陟则在巘，</p><p class="poem-stanza">复降在原。何以舟之？维玉及瑶，鞞琫容刀。</p><p class="poem-stanza">笃公刘，逝彼百泉。瞻彼溥原，乃陟南冈。乃觏于京，京师之野。</p><p class="poem-stanza">于时处处，于时庐旅，于时言言，于时语语。</p><p class="poem-stanza">笃公刘，于京斯依。跄跄济济，俾筵俾几。既登乃依，乃造其曹。</p><p class="poem-stanza">执豕于牢，酌之用匏。食之饮之，君之宗之。</p><p class="poem-stanza">笃公刘，既溥既长。既景乃冈，相其阴阳，观其流泉。其军三单，</p><p class="poem-stanza">度其隰原。彻田为粮，度其夕阳。豳居允荒。</p><p class="poem-stanza">笃公刘，于豳斯馆。涉渭为乱，取厉取锻，止基乃理。爰众爰有，</p><p class="poem-stanza">夹其皇涧。溯其过涧。止旅乃密，芮鞫之即。</p></div>',3)])])}const z=s(o,[["render",c]]);export{d as __pageData,z as default};
